# Blurbs are original Thai written from the canonical scene, not from commentaries.
# Every episode is (person id, bilara file, Pali needle or segment id, Thai note[, unit id]);
# the build stops if the needle is not in that file.

from people_data import p

ETADAGGA_FILES = [
    (188, 197), (198, 208), (209, 218), (219, 234), (235, 247), (248, 257), (258, 267),
]


def et(pid, n, text):
    lo, hi = next((a, b) for a, b in ETADAGGA_FILES if a <= n <= b)
    return (pid, f"an1.{lo}-{hi}", f"an1.{n}:1.1", "เอตทัคคะ: " + text)


